result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/ribbon.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildRibbon, curveOf, deviationAt } from '../src/ribbon.js';

// Fixture: 24 y-values of a decaying chirp.
const SAMPLES = Array.from({ length: 24 }, (_, i) => Math.sin(0.9 * i) * Math.exp(-i / 16));

describe('ribbon', () => {
  it('interpolates interior control points within 1e-3', () => {
    const mesh = buildRibbon(SAMPLES);
    for (let i = 1; i < SAMPLES.length - 1; i++) {
      expect(deviationAt(mesh, i)).toBeLessThan(1e-3);
    }
  });

  it('curve endpoints equal the end control points within 1e-9', () => {
    const mesh = buildRibbon(SAMPLES);
    const curve = curveOf(mesh);
    const first = curve.getPoint(0);
    const last = curve.getPoint(1);
    expect(first.distanceTo(curve.points[0])).toBeLessThan(1e-9);
    expect(last.distanceTo(curve.points[curve.points.length - 1])).toBeLessThan(1e-9);
  });

  it('mesh Box3 x-extent equals (n-1)*spacing within 1e-3', () => {
    const spacing = 0.5;
    const mesh = buildRibbon(SAMPLES, { spacing });
    const box = new THREE.Box3().setFromObject(mesh);
    const xExtent = box.max.x - box.min.x;
    expect(Math.abs(xExtent - (SAMPLES.length - 1) * spacing)).toBeLessThan(1e-3);
  });

  it('increasing tubeRadius grows the y-extent accordingly', () => {
    const r1 = 0.08;
    const r2 = 0.2;
    const m1 = buildRibbon(SAMPLES, { tubeRadius: r1 });
    const m2 = buildRibbon(SAMPLES, { tubeRadius: r2 });
    const b1 = new THREE.Box3().setFromObject(m1);
    const b2 = new THREE.Box3().setFromObject(m2);
    const growth = b2.max.y - b2.min.y - (b1.max.y - b1.min.y);
    expect(Math.abs(growth - 2 * (r2 - r1))).toBeLessThan(1e-3);
  });

  it('geometry index exists and triangle count matches the TubeGeometry formula', () => {
    const mesh = buildRibbon(SAMPLES);
    const geo = mesh.geometry;
    expect(geo.index).not.toBeNull();
    const tubularSegments = mesh.userData.tubularSegments;
    const radialSegments = mesh.userData.radialSegments;
    const expectedTriangles = tubularSegments * radialSegments * 2;
    expect(geo.index.count / 3).toBe(expectedTriangles);
  });
});
"})
