result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/ribbon.js", "content": "import * as THREE from 'three';

/**
 * Build a tube ("ribbon") mesh sweeping along a Catmull-Rom curve that
 * interpolates the sampled sound-wave points (i*spacing, samples[i]*2, 0).
 *
 * The tube surface is trimmed flush in x at both ends (vertex x-coordinates
 * are clamped to [0, (n-1)*spacing]), so the mesh's axis-aligned bounding
 * box spans exactly the control-point range.
 */
export function buildRibbon(samples, { spacing = 0.5, tubeRadius = 0.08 } = {}) {
  const points = samples.map((s, i) => new THREE.Vector3(i * spacing, s * 2, 0));
  const curve = new THREE.CatmullRomCurve3(points, false);
  const tubularSegments = 20 * (samples.length - 1);
  const radialSegments = 12;
  const geometry = new THREE.TubeGeometry(curve, tubularSegments, tubeRadius, radialSegments, false);

  // Trim flush in x: clamp every vertex into the control-point range.
  const maxX = (samples.length - 1) * spacing;
  const pos = geometry.attributes.position;
  for (let v = 0; v < pos.count; v++) {
    pos.setX(v, Math.min(maxX, Math.max(0, pos.getX(v))));
  }
  pos.needsUpdate = true;
  geometry.computeBoundingSphere();
  geometry.computeBoundingBox();

  const material = new THREE.MeshStandardMaterial({ color: 0x88aaff });
  const mesh = new THREE.Mesh(geometry, material);
  // Keep the curve and construction parameters accessible for analysis.
  mesh.userData.curve = curve;
  mesh.userData.spacing = spacing;
  mesh.userData.tubeRadius = tubeRadius;
  mesh.userData.tubularSegments = tubularSegments;
  mesh.userData.radialSegments = radialSegments;
  return mesh;
}

/** The Catmull-Rom curve underlying a ribbon mesh. */
export function curveOf(mesh) {
  return mesh.userData.curve;
}

/**
 * Distance from control point i to its closest approach on the discretized
 * curve: the polyline through `denseCount` (default 2000) uniformly spaced
 * dense samples of the curve. Since a Catmull-Rom spline interpolates its
 * control points, this stays near zero.
 */
export function deviationAt(mesh, i, denseCount = 2000) {
  const curve = curveOf(mesh);
  const target = curve.points[i];
  let prev = null;
  let minDistSq = Infinity;
  for (let k = 0; k < denseCount; k++) {
    const p = curve.getPoint(k / (denseCount - 1));
    if (prev !== null) {
      // Distance from target to segment [prev, p].
      const ab = p.clone().sub(prev);
      const lenSq = ab.lengthSq();
      let t = lenSq > 0 ? target.clone().sub(prev).dot(ab) / lenSq : 0;
      t = Math.max(0, Math.min(1, t));
      const d = prev.clone().addScaledVector(ab, t).distanceToSquared(target);
      if (d < minDistSq) minDistSq = d;
    }
    prev = p;
  }
  return Math.sqrt(minDistSq);
}
